AssistantMessageToolRequest(name='create', tool_call_id='function-call-2c645fc0-2bc9-465e-8cf5-e1ecb5874f5e', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', () => {
    const dialog = document.getElementById('confirm-dialog');
    const trigger = document.getElementById('delete-trigger');
    const cancelBtn = document.getElementById('cancel-btn');
    const confirmDeleteBtn = document.getElementById('confirm-delete-btn');

    // Open dialog
    trigger.addEventListener('click', () => {
        dialog.showModal();
        // The browser automatically moves focus. 
        // For destructive actions, it's safer to focus the cancel/secondary button 
        // to prevent accidental confirmation.
        cancelBtn.focus();
    });

    // Close on cancel
    cancelBtn.addEventListener('click', () => {
        dialog.close();
    });

    // Handle confirm delete
    confirmDeleteBtn.addEventListener('click', () => {
        console.log('Image deleted!');
        // In a real app, you'd perform the deletion logic here.
        dialog.close();

        // Visual feedback
        const imageWrapper = document.querySelector('.image-wrapper');
        imageWrapper.style.opacity = '0.3';
        imageWrapper.innerHTML = '<p style="padding: 2rem; color: var(--text-secondary);">Image deleted from library.</p>';
        trigger.disabled = true;
        trigger.style.opacity = '0.5';
        trigger.textContent = 'Deleted';
    });

    // Close when clicking on backdrop
    dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (
            rect.top <= event.clientY &&
            event.clientY <= rect.top + rect.height &&
            rect.left <= event.clientX &&
            event.clientX <= rect.left + rect.width
        );
        if (!isInDialog) {
            dialog.close();
        }
    });
});
