    border-radius: 8px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
    border: 1px solid var(--border-color);
}

header h1 {
    margin-top: 0;
    font-size: 1.5rem;
    border-bottom: 1px solid var(--border-color);
    padding-bottom: 1rem;
    margin-bottom: 1.5rem;
}

.image-wrapper {
    background-color: #000;
    border-radius: 4px;
    overflow: hidden;
    margin-bottom: 1.5rem;
    display: flex;
    justify-content: center;
}

.image-wrapper img {
    max-width: 100%;
    height: auto;
    display: block;
}

.actions {
    display: flex;
    justify-content: flex-end;
}

.btn {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 4px;
    font-weight: 600;
    cursor: pointer;
    border: none;
    transition: background-color 0.2s, transform 0.1s;
    font-size: 1rem;
}

.btn:active {
    transform: scale(0.98);
}

.btn:focus-visible {
    outline: var(--focus-outline);
    outline-offset: 2px;
}

.btn.trigger {
    background-color: var(--danger-color);
    color: white;
}

.btn.trigger:hover {
    background-color: var(--danger-hover);
}

/* Dialog Styles */
dialog {
    background-color: var(--surface-color);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 0;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.8);
    opacity: 0;
    transform: scale(0.9);
    transition: opacity 0.2s ease-out, transform 0.2s ease-out, display 0.2s ease-out allow-discrete;
}

dialog[open] {
    opacity: 1;
    transform: scale(1);
}

@starting-style {
    dialog[open] {
        opacity: 0;
        transform: scale(0.9);
    }
}

dialog::backdrop {
    background-color: rgba(0, 0, 0, 0);
    backdrop-filter: blur(0);
    transition: background-color 0.2s ease-out, backdrop-filter 0.2s ease-out, display 0.2s ease-out allow-discrete;
}

dialog[open]::backdrop {
    background-color: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(4px);
}

@starting-style {
    dialog[open]::backdrop {
        background-color: rgba(0, 0, 0, 0);
        backdrop-filter: blur(0);
    }
}

.dialog-content {
    padding: 2rem;
}

.dialog-content h2 {
    margin-top: 0;
    font-size: 1.25rem;
    color: var(--text-primary);
}

.dialog-content p {
    color: var(--text-secondary);
    line-height: 1.5;
    margin-bottom: 2rem;
}

.dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: 1rem;
}

.btn-secondary {
    background-color: #333;
    color: var(--text-primary);
}

.btn-secondary:hover {
    background-color: #444;
}

.btn-danger {
    background-color: var(--danger-color);
    color: white;
}

.btn-danger:hover {
    background-color: var(--danger-hover);
}

/* Ensure background doesn't scroll when dialog is open */
body:has(dialog[open]) {
    overflow: hidden;
}
