         cancelBtn.focus();
     });

     // Close on cancel
     cancelBtn.addEventListener('click', () => {
         dialog.close();
     });

     // Handle confirm delete
     confirmDeleteBtn.addEventListener('click', () => {
         console.log('Image deleted!');
         // In a real app, you'd perform the deletion logic here.
         dialog.close();

         // Visual feedback
         const imageWrapper = document.querySelector('.image-wrapper');
         imageWrapper.style.opacity = '0.3';
         imageWrapper.innerHTML = '<p style="padding: 2rem; color: var(--text-secondary);">Image deleted from library.</p>';
         trigger.disabled = true;
         trigger.style.opacity = '0.5';
         trigger.textContent = 'Deleted';
     });

     // Close when clicking on backdrop
     dialog.addEventListener('click', (event) => {
         const rect = dialog.getBoundingClientRect();
         const isInDialog = (
             rect.top <= event.clientY &&
             event.clientY <= rect.top + rect.height &&
             rect.left <= event.clientX &&
             event.clientX <= rect.left + rect.width
         );
         if (!isInDialog) {
             dialog.close();
         }
     });
 });

